-- Original practice instructions. Idempotent append, retaining quizzes and previous material.
with authored(lesson_no,section) as (values
  (0, $curriculum${"heading": "Od menu do pierwszego szkicu", "text": "W desktopowym środowisku Drafting & Annotation karta Home grupuje Draw (tworzenie), Modify (zmiany) i Layers (warstwy). W warsztacie wybierz Rysuj → Prostokąt. Wpisz 100,100 i naciśnij Enter, a potem 600,400 i Enter. Powinien powstać prostokąt szeroki na 500 i wysoki na 300 jednostek. Wybierz Kreskowanie i wskaż jego środek. Zobaczysz, że rozmiar obrysu pozostaje ten sam, choć zmienił się wygląd wnętrza."}$curriculum$::jsonb),
  (1, $curriculum${"heading": "Wstążka, wiersz poleceń i stan rysunku", "text": "Polecenie można zacząć ikoną albo wpisem w wierszu poleceń. Po uruchomieniu patrz na komunikat nad polem wpisu: dla CIRCLE najpierw potrzebujesz środka, a później promienia lub punktu na obwodzie. Pasek stanu steruje pomocą rysunkową. Siatka F7 wyświetla linie orientacyjne, OSNAP F3 szuka wskazanych punktów obiektów, a ORTHO F8 ogranicza swobodne wskazanie kierunku do poziomu lub pionu. Włącz każdy osobno, aby odróżnić ich działanie."}$curriculum$::jsonb),
  (3, $curriculum${"heading": "Jednostka modelu, skala arkusza", "text": "Przed rysowaniem ustal znaczenie jednej jednostki z opisem projektu. Jeśli jedna jednostka oznacza 1 mm, szerokość 900 mm wpisujesz jako 900. Rysuj w modelu w rzeczywistej wielkości. Skalę arkusza ustawiasz na etapie prezentacji lub wydruku. Pomiar 900 jednostek w pliku narysowanym w milimetrach ma dać 900 mm niezależnie od powiększenia na ekranie. Przy dołączaniu innego pliku zweryfikuj jednostki obu rysunków na jednym znanym wymiarze."}$curriculum$::jsonb),
  (4, $curriculum${"heading": "Współrzędne bez zgadywania", "text": "W wierszu poleceń wpis 100,100 wskazuje położenie od początku układu. Wpis @250,0 po punkcie 100,100 daje punkt 350,100. Znak @ oznacza przesunięcie od ostatniego punktu. Przy wpisie 175.5,80 kropka jest separatorem części dziesiętnej, a przecinek rozdziela X i Y. Przećwicz L, Enter, 100,100, Enter, @250,0, Enter, potem zakończ. Długość wynosi 250 jednostek. W warsztacie widoczne pole obejmuje X od 0 do 1000 i Y od 0 do 600."}$curriculum$::jsonb),
  (5, $curriculum${"heading": "Odcinek, obrys i promień", "text": "L uruchamia LINE i pozwala tworzyć pojedyncze odcinki po kolejnych punktach. PL uruchamia PLINE. Jej połączone segmenty zachowują się jak jeden obiekt, a opcja Close domyka polilinię. REC uruchamia RECTANG i oczekuje dwóch przeciwległych narożników. C uruchamia CIRCLE przy gotowym wierszu poleceń. Po środku 300,250 wpisz promień 60. Średnica będzie miała 120 jednostek. Narysuj te same trzy krawędzie raz przez LINE i raz przez PLINE, a potem zaznacz jedną krawędź każdej figury."}$curriculum$::jsonb),
  (6, $curriculum${"heading": "Enter, Esc i wycofanie operacji", "text": "Wpisz pełną nazwę lub alias i potwierdź Enterem. Każdy podany punkt zatwierdzasz osobno. Przy LINE pusty Enter kończy dodawanie odcinków. Esc przerywa aktywne polecenie lub usuwa zaznaczenie. Ctrl+Z cofa zmianę już zapisaną w historii edycji. W warsztacie wybierz prostokąt, wskaż tylko pierwszy narożnik i użyj Anuluj. Spróbuj ponownie z dwoma narożnikami. Następnie użyj Cofnij, aby porównać anulowanie polecenia z cofnięciem ukończonej figury."}$curriculum$::jsonb),
  (7, $curriculum${"heading": "Warstwy przed rysowaniem", "text": "W desktopowym AutoCAD polecenie LA (LAYER) otwiera zarządzanie warstwami. Wybierz aktywną warstwę przed rysowaniem kolejnych elementów. W warsztacie ustaw Obrys i narysuj prostokąt, potem wybierz Osie i dodaj odcinek przez środek. Nowy odcinek otrzyma kolor warstwy Osie. Sprawdź, czy istniejący obrys zachował swój kolor. W projekcie nazwy warstw powinny odpowiadać ich zadaniu, np. obrys, osie i wymiary. Łatwiej wtedy znaleźć i kontrolować grupy elementów."}$curriculum$::jsonb),
  (9, $curriculum${"heading": "Wypełnianie zamkniętego obrysu", "text": "H uruchamia HATCH. W AutoCAD możesz wskazać punkt wewnątrz obszaru lub wybrać jego granice. W warsztacie wybierz Rysuj → Kreskowanie i wskaż wnętrze figury. Linie ukośne pomagają odróżnić obszary na rysunku, a typ SOLID pokrywa obszar jednolicie. Narysuj trójkąt polilinią: 150,100 → 650,100 → 400,450, użyj Zamknij obrys, a potem wskaż 400,200 dla kreskowania. Gdy otwarta polilinia nie przyjmuje wypełnienia, sprawdź jej końce i zamknij kontur."}$curriculum$::jsonb),
  (10, $curriculum${"heading": "Dobierz polecenie do kształtu", "text": "Home → Draw daje dostęp do linii, polilinii, prostokąta, okręgu i kreskowania. Linia pasuje do pojedynczej osi, zamknięta polilinia do nieregularnego obrysu, a RECTANG oszczędza wskazywanie czterech narożników prostokąta. W warsztacie narysuj prostokąt 200,150 → @400,250 i okrąg o środku 400,275 oraz promieniu 50. Wypełnij okrąg, potem kliknij w prostokącie poza okręgiem, aby wypełnić prostokąt innym wzorem. Sprawdź liczbę figur i wypełnień pod rysunkiem."}$curriculum$::jsonb),
  (11, $curriculum${"heading": "Przesuń i skopiuj o zadaną odległość", "text": "Zaznacz figurę, wybierz MOVE albo COPY, wskaż punkt bazowy i podaj punkt docelowy. O położeniu decyduje różnica współrzędnych między tymi punktami. Gdy punktem bazowym jest 100,100, a celem @300,0, figura przesunie się o 300 w prawo. Przy COPY powstanie kopia, a oryginał zostanie na miejscu. ROTATE obraca wokół wskazanej bazy, a SCALE zmienia rozmiar względem bazy. Współczynnik skali 2 podwaja długości, a 0.5 dzieli je przez dwa."}$curriculum$::jsonb),
  (12, $curriculum${"heading": "F3 a F8 na tym samym zadaniu", "text": "Włącz OSNAP (F3), gdy nowy odcinek ma zacząć się na istniejącym narożniku lub końcu. W warsztacie zbliż kliknięcie do punktu figury i obserwuj, gdzie trafi znacznik. Włącz ORTHO (F8), gdy chcesz wskazać poziomy lub pionowy kierunek kursorem. Wpisane współrzędne pozwalają zadać dokładny punkt niezależnie od ustawienia kursora. Sprawdź to na dwóch odcinkach: pierwszy wskaż myszą z F8, dla drugiego wpisz @200,100."}$curriculum$::jsonb),
  (16, $curriculum${"heading": "Długość odcinka i opis wymiaru", "text": "Polecenie DIST (alias DI) służy w AutoCAD do pomiaru odległości między dwoma wskazanymi punktami. Narzędzia na karcie Annotate → Dimensions wstawiają na rysunku czytelną adnotację. Linear przydaje się do wymiaru poziomego lub pionowego, Aligned prowadzi linię wymiarową równolegle do skośnej krawędzi. W warsztacie wybierz View i zmierz zaznaczony prostokąt. Sprawdź jego rozmiar z różnicy współrzędnych narożników. To dwa sposoby skontrolowania tej samej geometrii."}$curriculum$::jsonb),
  (27, $curriculum${"heading": "Kontrola geometrii przed przekazaniem", "text": "Najpierw sprawdź rzeczywisty rozmiar na odcinku o znanej długości. Następnie obejrzyj połączenia i wierzchołki w powiększeniu. Przy zamkniętym konturze oceń też, czy nie ma samoprzecięć, podwójnych linii i przerw przy wierzchołkach. Próbne kreskowanie pomaga znaleźć niezamknięty obszar. Ostatecznie porównaj wymiar modelu, skalę arkusza i wymiar na PDF. Na przykład 1000 mm w skali 1:20 daje 50 mm na poprawnie wydrukowanym arkuszu."}$curriculum$::jsonb)
)
update public.ta_lessons lesson
set material=jsonb_set(lesson.material,'{sections}',
    coalesce(lesson.material->'sections','[]'::jsonb)||jsonb_build_array(authored.section),true),
    updated_at=now()
from authored
where lesson.course_slug='autocad-skroty' and lesson.lesson_no=authored.lesson_no
and not exists (
  select 1 from jsonb_array_elements(coalesce(lesson.material->'sections','[]'::jsonb)) as existing(section)
  where existing.section->>'heading'=authored.section->>'heading'
)
returning lesson.lesson_no,authored.section->>'heading' as added_section;
